  str_draw_card_pool_name_40001 = "Recrutamento Especial de Halloween",
  str_draw_card_pool_des_40001 = "Recrute 10 vezes e receba um dos Aurorians 6 Estrelas em destaque!",
  str_draw_card_pool_title_40001_1 = "Recrutamento Especial de Halloween",
  str_draw_card_pool_title_40001_2 = "Após recrutar 10 vez, o Recrutamento Especial de Halloween será encerrado!",
  str_draw_card_pool_detail_title_40001 = "Inf. Rec. Especial de Halloween",
  str_draw_card_pool_detail_sub_desc40001_1 = "Esse é um recrutamento especial de Halloween. Você precisa comprar o item 10x Espírito de Recrutamento Especial na loja para participar. Use o item 10x Espírito de Recrutamento Especial para recrutar 10 vezes seguidas. Quando usar esse item, o Recrutamento Especial de Halloween será encerrado.\n\nParticipe desse recrutamentfo e garanta pelo menos um Aurorian 6 Estrelas (<color=#ffbb00>Carleen, Uriel, Migard ou Irridon</color>). A probabilidade de obter personagens de avaliações diferentes nos 9 sorteios restantes será a mesma que a probabilidade de recrutamento normal, o que significa que você tem chanca de obter mais Aurorians 6 Estrelas, além de um dos garantidos mencionados anteriormente. Veja a tabela abaixo para certos Aurorians e chances de recrutamento.\n\nObserve que o Recrutamento Especial de Halloween é um recrutamento limitado. Portanto, recomendamos que você conclua esse recrutamento especial antes do final do período.\n\nSe você comprou o item 10x Espírito de Recrutamento Especial, mas não conseguiu participar do evento de recrutamento especial, seu item 10x Espírito de Recrutamento Especial será convertido em 3.000 Lumâmbar depois que o período de recrutamento se encerrar. O Lumâmbar será enviado diretamente para seu correio no jogo.",
  str_draw_card_pool_detail_sub_desc40001_2 = "Todos os Aurorians Recrutáveis\nAurorian 6 Estrelas: 2%\nGram/Revy/Smokey/Fleur/Beryl/Hiiro/Sinsa/Eve/Uriel/Carleen/Sharona/Sariel/Raphaela/Connolly/Charon/Eicy/Victoria/Jona/Nikinis/Gabriela/Migard/Michele/Gronru/Irridon/Wrath\nAurorians 5 Estrelas: 9,5%\nGenevieve/Taki/Corax/Barton/Kleken/Philyshy/Noah/Hydrad/Benny e Curo/Regina/Faust/Maggie/Istvan/Barbara/Leona/Areia/Pact/Sikare/Louise/Odi/Cuscuta/Dayna/Schwartz/Nemesis/Beverly/Keating/Vivian/Mia\nAurorians 4 Estrelas: 33%\nTweety/Pasolo/Jane/Kuma e Pengy/Srta. Blanc/Michenny/Chloe/Constantine/Patty e Patsy/Joanie Boom/Alice/Brock/Nails/Chandra/Sylva/Lester/Jola/Wendy/Uriah/Tessa/Ansia/Nadine/Rabbie/Lilliam/Kafka\nAurorians 3 Estrelas: 55,5%\nSeleucid/Zoya/White Dwarf/Korgon/Sork e Bekk/Tiny One/Pepi/Chainsaw Rick/Jomu/Clover/Ophina/Dove/Leah/Angel/Unimet/Eho/Amy",
  str_draw_card_pool_name_40003 = "Special Christmas Recruitment",
  str_draw_card_pool_des_40003 = "Recrute 10 vezes e receba um dos Aurorians 6 Estrelas em destaque!",
  str_draw_card_pool_title_40003_1 = "Special Christmas Recruitment",
  str_draw_card_pool_title_40003_2 = "After recruiting 10 times, the Special Christmas Recruitment will be closed!",
  str_draw_card_pool_detail_title_40003 = "Regras p/ Recrutar",
  str_draw_card_pool_detail_sub_desc40003_1 = "This is a special Christmas recruitment. You need to buy the specified 10× Special Recruitment Spirit item from the store to take part. Use the specified 10× Special Recruitment Spirit item to recruit 10 times in a row. Once you use this item, the Special Christmas Recruitment will be closed.\n\nTake part in this recruitment, and you're guaranteed to get at least one 6-Star Aurorian (<color=#ffbb00>Carleen, Uriel, Migard, or Irridon</color>). The probability of obtaining characters of different ratings in the remaining 9 recruitment draws will be the same as the probability of a normal recruitment. Meaning you might have a chance of obtaining more Aurorian 6 Estrelas in addition to one of the aforementioned Aurorian 6 Estrelas. See the table below for specific Aurorians and recruitment rates.\n\nPlease note that the Special Christmas Recruitment is a limited-time recruitment pool, therefore, it is recommended that you complete this special recruitment before the end of the special recruitment period.\n\nIf you purchased the 10× Special Recruitment Spirit item but fail to take part in the special recruitment event, your 10× Special Recruitment Spirit will be converted into 3,000 Lumamber after the special recruitment period ends. The Lumamber will be sent directly to your in-game mailbox.",
  str_draw_card_pool_detail_sub_desc40003_2 = "Todos os Aurorians Recrutáveis\nAurorian 6 Estrelas: 2.0%\nPaloma/Gram/Revy/Smokey/Fleur/Beryl/Hiiro/Sinsa/Eve/Uriel/Carleen/Sharona/Sariel/Raphael/Connolly/Charon/Eicy/Victoria/Jona/Nikinis/Gabriel/Migard/Michael/Gronru/Irridon/Wrath\nAurorian 5 Estrelas: 9.5%\nNaroxel/Genevieve/Taki/Corax/Barton/Kleken/Philyshy/Noah/Hydrad/Benny and Curo/Regina/Faust/Maggie/Istvan/Barbara/Leona/Areia/Pact/Sikare/Louise/Odi/Cuscuta/Dayna/Schwartz/Nemesis/Beverly/Keating/Vivian/Mia\nAurorian 4 Estrelas: 33.0%\nTweety/Pasolo/Jane/Kuma & Pengy/Ms. Blanc/Michenny/Chloe/Constantine/Patty & Patsy/Joanie Boom/Alice/Brock/Nails/Chandra/Sylva/Lester/Jola/Wendy/Uriah/Tessa/Ansia/Nadine/Rabbie/Lilliam/Kafka\nAurorian 3 Estrelas: 55.5%\nSeleucid/Zoya/White Dwarf/Korgon/Sork & Bekk/Tiny One/Pepi/Chainsaw Rick/Jomu/Clover/Ophina/Dove/Leah/Angel/Unimet/Eho/Amy",
  str_draw_card_pool_name_40004 = "Recrutamento Festivo Especial",
  str_draw_card_pool_des_40004 = "Recruit 10 times to get one of the featured 6-Star Aurorians!",
  str_draw_card_pool_title_40004_1 = "Recrutamento Festivo Especial",
  str_draw_card_pool_title_40004_2 = "O Recrutamento Festivo Especial será encerrado após 10 recrutamentos.",
  str_draw_card_pool_detail_title_40004 = "Informações especiais de recrutamento festivo",
  str_draw_card_pool_detail_sub_desc40004_1 = "Este é um Recrutamento Festivo Especial. Você precisa comprar o item 10x Special Recruitment Spirit especificado na loja para participar. Use o item Espírito de Recrutamento Especial 10x especificado para recrutar 10 vezes seguidas. Depois de usar este item, o Recrutamento Festivo Especial será fechado.\n\nParticipe deste recrutamento e você terá a garantia de obter pelo menos um Auroriano de 6 Estrelas (<color=#ffbb00>Betel, Sinsa, Paloma ou Revy</color>). A probabilidade de obter personagens de diferentes classificações nos 9 sorteios restantes será a mesma que a probabilidade de um recrutamento normal. O que significa que você pode ter a chance de obter mais Aurorianos de 6 Estrelas além de um dos Aurorianos de 6 Estrelas mencionados acima. Veja a tabela abaixo para aurorianos específicos e taxas de recrutamento.\n\nObserve que o Recrutamento Festivo é um pool de recrutamento por tempo limitado, portanto, é recomendável concluir este recrutamento especial antes do final do período de recrutamento especial.\n\nSe você comprou o item 10x Special Recruitment Spirit, mas não participou do evento Special Festive Recruitment, o 10x Special Recruitment Spirit será convertido em 3.000 Lumamber após o término do evento. O Lumamber será enviado diretamente para sua caixa de correio no jogo.",
  str_draw_card_pool_detail_sub_desc40004_2 = "Todos os Aurorianos Recrutáveis\nAurorianos de 6 Estrelas: 2,0%\nYao/Amemori/Rinne/Ruby/Florine/Siobhan/Novio/Hedy/Bethel/Luke/Paloma/Gram/Revy/Smokey/Fleur/Beryl/Hiiro/Sinsa/Eve/Uriel/Carleen/Sharona/Sariel/Raphael/Connolly/ Caronte/Eicy/Victoria/Jona/Nikinis/Gabriel/Migard/Michael/Gronru/Irridon/Ira\nAurorianos de 5 estrelas: 9,5%\nKayano/Erica/Robyn/Cordy/Naroxel/Genevieve/Taki/Corax/Barton/Kleken/Philyshy/Noah/Hydrad/Benny e Curo/Regina/Faust/Maggie/Istvan/Barbara/Leona/Areia/Pact/Sikare/Louise/ Odi/Cuscuta/Dayna/Schwartz/Nemesis/Beverly/Keating/Vivian/Mia\nAurorianos de 4 estrelas: 33,0%\nHachi & Gin/Tweety/Pasolo/Jane/Kuma & Pengy/Ms. Blanc/Michenny/Chloe/Constantine/Patty & Patsy/Joanie Boom/Alice/Brock/Nails/Chandra/Sylva/Lester/Jola/Wendy/Uriah/Tessa/Ansia/Nadine/Rabbie/Lilliam/Kafka\nAurorianos de 3 estrelas: 55,5%\nSeleucid/Zoya/White Dwarf/Korgon/Sork & Bekk/Tiny One/Pepi/Chainsaw Rick/Jomu/Clover/Ophina/Dove/Leah/Angel/Unimet/Eho/Amy",
  str_draw_card_pool_name_40005 = "Recrutamento Festivo de Vento de Verão",
  str_draw_card_pool_title_40005_2 = "Recrute 10 vezes e receba um dos Aurorians 6 Estrelas em destaque!",
  str_draw_card_pool_title_40005_1 = "Recrutamento Festivo de Vento de Verão",
  str_draw_card_pool_des_40005 = "O recrutamento do Summer Wind Festive será encerrado após 10 recrutamentos.",
  str_draw_card_pool_detail_title_40005 = "Informações de recrutamento do Festivo de Vento de Verão",
  str_draw_card_pool_detail_sub_desc40005_1 = "Este é o Recrutamento Festivo do Vento de Verão. Você precisa comprar o item 10× Summer Recruit Spirit especificado na loja para participar. Usá-lo recrutará do banner 10 vezes. Depois de usar este item, o Recrutamento Festivo do Vento de Verão será fechado.\n\nParticipe deste recrutamento e você terá a garantia de obter pelo menos um dos seguintes Aurorianos de 6 Estrelas: <color=#ffbb00>Azure, Noviol, Florine ou Hedy</color>. A probabilidade de obter personagens de diferentes classificações nos 9 sorteios restantes será a mesma que a probabilidade de um recrutamento normal. O que significa que você pode ter a chance de obter mais Aurorianos de 6 Estrelas além de um dos Aurorianos de 6 Estrelas mencionados acima. Veja a tabela abaixo para aurorianos específicos e taxas de recrutamento.\n\nObserve que o Recrutamento Festivo do Vento de Verão é um pool de recrutamento por tempo limitado, portanto, é recomendável que você conclua este recrutamento especial antes do final do período de recrutamento festivo.\n\nSe você comprou o item 10× Summer Recruit Spirit, mas não participou do evento de recrutamento festivo, seu 10× Summer Recruit Spirit será convertido em 3.000 Lumamber após o término do período de recrutamento festivo. O Lumamber será enviado diretamente para sua caixa de correio no jogo.",
